#include <iostream>
using namespace std;

int main() {
    // 掷两枚骰子，求点数之和为 7 的概率
    int favorable = 0, total = 0;
    for (int i = 1; i <= 6; i++) {
        for (int j = 1; j <= 6; j++) {
            total++;
            if (i + j == 7) {
                favorable++;
            }
        }
    }
    cout << "总情况数: " << total << endl;
    cout << "有利情况数: " << favorable << endl;
    cout << "概率: " << favorable << "/" << total;
    cout << " = " << (double)favorable / total << endl;

    // 利用对立事件：至少一枚为 6 的概率
    int noneSix = 0;
    for (int i = 1; i <= 6; i++)
        for (int j = 1; j <= 6; j++)
            if (i != 6 && j != 6) noneSix++;
    double pAtLeastOneSix = 1.0 - (double)noneSix / total;
    cout << "至少一枚为6的概率: " << pAtLeastOneSix << endl;

    return 0;
}

#include <iostream>
using namespace std;

long long C(int n, int m) {
    if (m > n - m) m = n - m;
    long long result = 1;
    for (int i = 0; i < m; i++) {
        result = result * (n - i) / (i + 1);
    }
    return result;
}

int main() {
    // 从52张扑克牌中抽5张，求恰好3张是红心的概率
    long long favorable = C(13, 3) * C(39, 2);
    long long total = C(52, 5);
    cout << "有利情况数: " << favorable << endl;
    cout << "总情况数: " << total << endl;
    cout << "概率约为: " << (double)favorable / total << endl;

    // 10个人中选3个人组成委员会，甲和乙都在委员会的概率
    long long fav2 = C(8, 1); // 甲乙已选，再从剩余8人选1个
    long long total2 = C(10, 3);
    cout << "甲乙都在的概率: " << (double)fav2 / total2 << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    // 袋中有3个红球和2个蓝球，不放回取2个
    // 求：第2个是红球的前提下，第1个也是红球的概率
    // P(第1个红 | 第2个红) = P(两个都红) / P(第2个红)

    int red = 3, blue = 2, total = 5;

    double pBothRed = (double)(red * (red - 1)) / (total * (total - 1));
    cout << "P(两个都红): " << pBothRed << endl;

    double pSecondRed = (double)red / total;
    cout << "P(第2个红): " << pSecondRed << endl;

    double pFirstRedGivenSecond = pBothRed / pSecondRed;
    cout << "P(第1个红|第2个红): " << pFirstRedGivenSecond << endl;

    // 直接验证：第2个是红球的情况
    // 第2个红时，相当于从4个球(取决于第1个取了什么)中看第1个
    // 第2个红说明剩下4个球中3红1蓝(如果第1个蓝)或2红2蓝(如果第1个红)
    // P(第1红且第2红) = 3/5 * 2/4 = 6/20 = 3/10
    // P(第2红) = 3/5（对称性）
    // P(第1红|第2红) = 3/10 / 3/5 = 1/2
    cout << "验证: " << (double)(3 * 2) / (5 * 4) / ((double)3 / 5) << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    // 掷骰子的期望
    double e = 0;
    for (int i = 1; i <= 6; i++) {
        e += i * (1.0 / 6);
    }
    cout << "骰子点数的期望: " << e << endl;

    // 掷两枚骰子，点数之和的期望
    double e2 = 0;
    for (int i = 1; i <= 6; i++) {
        for (int j = 1; j <= 6; j++) {
            e2 += (i + j) * (1.0 / 36);
        }
    }
    cout << "两枚骰子之和的期望: " << e2 << endl;
    cout << "验证（用线性性）: " << 2 * e << endl;

    // 彩票问题：100张彩票，1张中奖1000元，每张5元
    // 买一张的期望收益
    double winProb = 1.0 / 100;
    double expectGain = 1000 * winProb + 0 * (1 - winProb);
    double cost = 5;
    cout << "期望奖金: " << expectGain << " 元" << endl;
    cout << "期望净收益: " << expectGain - cost << " 元" << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    // n个人随机排列，求固定点（位置不变的人）的期望个数
    int n = 10;

    // 方法：指示变量
    // I_i = 1 如果第i个人在第i个位置
    // P(I_i=1) = 1/n（第i个位置等可能放任何一个人）
    // E(固定点数) = ΣE(I_i) = n × (1/n) = 1
    double eFixPoint = 0;
    for (int i = 1; i <= n; i++) {
        eFixPoint += 1.0 / n;
    }
    cout << "固定点期望个数: " << eFixPoint << endl;

    // n条线段，随机选两条，求交点数的期望
    // I_ij = 1 如果线段i和线段j相交
    // E(交点数) = Σ E(I_ij)
    // 对每对(i,j)，P(相交) 取决于具体问题
    int lines = 5;
    double pIntersect = 0.3;
    int pairs = lines * (lines - 1) / 2;
    double eCross = pairs * pIntersect;
    cout << "交点期望数: " << eCross << endl;

    // 掷n枚骰子，点数之和的期望
    int dice = 5;
    double eSum = dice * 3.5;
    cout << dice << "枚骰子之和的期望: " << eSum << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    // 三个工厂生产零件：
    // 甲厂产量占50%，次品率2%
    // 乙厂产量占30%，次品率3%
    // 丙厂产量占20%，次品率5%
    // 求任取一个零件是次品的概率

    double pA = 0.50, defectA = 0.02;
    double pB = 0.30, defectB = 0.03;
    double pC = 0.20, defectC = 0.05;

    double pDefect = pA * defectA + pB * defectB + pC * defectC;
    cout << "次品概率: " << pDefect << endl;
    cout << "即 " << pDefect * 100 << "%" << endl;

    // 天气问题：
    // 晴天概率0.6，雨天概率0.3，阴天概率0.1
    // 晴天迟到的概率0.1，雨天0.3，阴天0.2
    // 求迟到的概率
    double pSunny = 0.6,  lateSunny = 0.1;
    double pRainy = 0.3,  lateRainy = 0.3;
    double pCloudy = 0.1, lateCloudy = 0.2;

    double pLate = pSunny * lateSunny + pRainy * lateRainy + pCloudy * lateCloudy;
    cout << "迟到概率: " << pLate << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    // 疾病检测问题：
    // 发病率 1%（先验概率）
    // 检测准确率：有病检出阳性 99%，无病检出阴性 95%
    // 问：检测为阳性时，真正有病的概率是多少？

    double pDisease = 0.01;
    double pNoDisease = 0.99;
    double pPositiveGivenDisease = 0.99;
    double pPositiveGivenNoDisease = 0.05;

    // 全概率公式求 P(阳性)
    double pPositive = pDisease * pPositiveGivenDisease
                     + pNoDisease * pPositiveGivenNoDisease;
    cout << "P(阳性) = " << pPositive << endl;

    // 贝叶斯公式求 P(有病|阳性)
    double pDiseaseGivenPositive = pDisease * pPositiveGivenDisease / pPositive;
    cout << "P(有病|阳性) = " << pDiseaseGivenPositive << endl;
    cout << "即约 " << pDiseaseGivenPositive * 100 << "%" << endl;

    // 三工厂问题续：已知是次品，来自各工厂的概率
    double pA = 0.50, defectA = 0.02;
    double pB = 0.30, defectB = 0.03;
    double pC = 0.20, defectC = 0.05;
    double pDefect = pA * defectA + pB * defectB + pC * defectC;

    cout << "来自甲厂: " << pA * defectA / pDefect << endl;
    cout << "来自乙厂: " << pB * defectB / pDefect << endl;
    cout << "来自丙厂: " << pC * defectC / pDefect << endl;

    return 0;
}

#include <iostream>
