using namespace std;

long long C(int n, int m) {
    if (m > n - m) m = n - m;
    long long result = 1;
    for (int i = 0; i < m; i++)
        result = result * (n - i) / (i + 1);
    return result;
}

int main() {
    // 二项分布 B(n=5, p=0.3)：5次实验，每次成功概率0.3
    int n = 5;
    double p = 0.3;

    cout << "二项分布 B(5, 0.3):" << endl;
    for (int k = 0; k <= n; k++) {
        double pk = C(n, k) * pow(p, k) * pow(1 - p, n - k);
        cout << "  P(X=" << k << ") = " << pk << endl;
    }
    cout << "  期望 E(X) = np = " << n * p << endl;
    cout << "  方差 D(X) = np(1-p) = " << n * p * (1 - p) << endl;

    // 几何分布 G(p=0.2)：首次成功所需次数
    double pg = 0.2;
    cout << "\n几何分布 G(0.2):" << endl;
    double cumProb = 0;
    for (int k = 1; k <= 10; k++) {
        double pk = pow(1 - pg, k - 1) * pg;
        cumProb += pk;
        cout << "  P(X=" << k << ") = " << pk << "  累积: " << cumProb << endl;
    }
    cout << "  期望 E(X) = 1/p = " << 1 / pg << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    // 掷两枚骰子：A=第一枚为6, B=第二枚为6
    double pA = 1.0 / 6;
    double pB = 1.0 / 6;
    double pBoth = 1.0 / 36;

    cout << "P(A)=" << pA << ", P(B)=" << pB << endl;
    cout << "P(A)*P(B)=" << pA * pB << ", P(A∩B)=" << pBoth << endl;
    cout << "独立？" << (pBoth == pA * pB ? "是" : "否") << endl;

    // 不独立的例子：掷一枚骰子
    // A=偶数{2,4,6}, B=大于3{4,5,6}
    double pEven = 3.0 / 6;
    double pGT3 = 3.0 / 6;
    double pEvenAndGT3 = 2.0 / 6; // {4,6}
    cout << "\nP(偶数)=" << pEven << ", P(>3)=" << pGT3 << endl;
    cout << "P(偶数)*P(>3)=" << pEven * pGT3 << endl;
    cout << "P(偶数且>3)=" << pEvenAndGT3 << endl;
    cout << "独立？" << (pEvenAndGT3 == pEven * pGT3 ? "是" : "否") << endl;

    // 三枚硬币同时抛，至少一枚正面的概率
    double pAllTail = 0.5 * 0.5 * 0.5;
    double pAtLeastOneHead = 1 - pAllTail;
    cout << "\n至少一枚正面: " << pAtLeastOneHead << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    // 问题：从位置0出发，每次掷骰子(1-6)前进对应步数
    // 到达或超过位置n时停止，求期望掷骰子次数
    // n = 10 为例

    int n = 10;
    double dp[20] = {};

    for (int i = n - 1; i >= 0; i--) {
        double sum = 0;
        for (int d = 1; d <= 6; d++) {
            int next = i + d;
            if (next >= n) {
                sum += 1;
            } else {
                sum += 1 + dp[next];
            }
        }
        dp[i] = sum / 6.0;
    }

    cout << "从位置0到" << n << "的期望步数: " << dp[0] << endl;

    // 概率DP：n枚硬币，每枚正面概率p，求恰好k枚正面的概率
    int coins = 5;
    double p = 0.6;
    double prob[10][10] = {};
    prob[0][0] = 1.0;

    for (int i = 1; i <= coins; i++) {
        for (int j = 0; j <= i; j++) {
            if (j > 0)
                prob[i][j] += prob[i-1][j-1] * p;
            prob[i][j] += prob[i-1][j] * (1 - p);
        }
    }

    cout << "\n恰好k枚正面的概率:" << endl;
    for (int k = 0; k <= coins; k++) {
        cout << "  k=" << k << ": " << prob[coins][k] << endl;
    }

    return 0;
}
